function collectTextRoles(el,oldRoles={}){const roles={};el.querySelectorAll('.textRoleRow').forEach(row=>{const old=oldRoles[row.dataset.role]||{},font=row.querySelector('.textRoleFontFamily').value;roles[row.dataset.role]={enabled:row.querySelector('.textRoleEnabled').checked,text:row.querySelector('.textRoleText').value.trim(),colorEnabled:row.querySelector('.textRoleColorEnabled').checked,color:row.querySelector('.textRoleColor').value,size:row.querySelector('.textRoleSizeEnabled').checked?clamp(row.querySelector('.textRoleSize').value,12,400,32):0,fontFamily:roleFontOptions.some(x=>x[0]===font)?font:'global',mode:row.querySelector('.textRoleMode').value==='image'?'image':'text',imageUrl:old.imageUrl||'',imageName:old.imageName||'',imageSize:clamp(row.querySelector('.textRoleImageSize').value,20,600,120),positionEnabled:row.querySelector('.textRolePositionEnabled').checked,x:clamp(row.querySelector('.textRoleX').value,0,100,50),y:clamp(row.querySelector('.textRoleY').value,0,100,50)}});return roles}
const collectGachaBeforeTextRoles=window.collectGacha;window.collectGacha=function(){const old=(state.gacha?.patterns||[]).map(x=>JSON.parse(JSON.stringify(x.textRoles||{})));collectGachaBeforeTextRoles();document.querySelectorAll('#gachaPatterns > .gachaPattern').forEach((el,i)=>{const p=state.gacha?.patterns?.[i],editor=el.querySelector('.textRoleEditor[data-text-scope="gacha"]');if(!p||!editor)return;p.textRoles=collectTextRoles(el,old[i]);p.textGlowEnabled=editor.querySelector('.unifiedGlowEnabled')?.checked===true;p.textGlowColor=editor.querySelector('.unifiedGlowColor')?.value||p.textGlowColor||'#e52b3c';p.textGlowStrength=clamp(editor.querySelector('.unifiedGlowStrength')?.value,0,40,12)})};
