const collectGachaBeforeOutcomeImageSizes=window.collectGacha;window.collectGacha=function(){const old=(state.gacha?.patterns||[]).map(p=>({id:p.id,outcomes:JSON.parse(JSON.stringify(p.outcomes||[])),upperOutcomes:JSON.parse(JSON.stringify(p.upperOutcomes||[]))}));collectGachaBeforeOutcomeImageSizes();document.querySelectorAll('#gachaPatterns > .gachaPattern').forEach((el,i)=>{const p=state.gacha?.patterns?.find(item=>String(item.id)===String(el.dataset.id))||state.gacha?.patterns?.[i],before=old.find(item=>String(item.id)===String(el.dataset.id))||old[i];if(!p)return;const read=(rows,items,oldItems)=>items.map((x,j)=>{const row=rows[j],prior=oldItems?.[j]||{};if(!row)return {...prior,...x};return {...x,spinImageSize:clamp(row.querySelector('.outcomeSpinImageSize')?.value??prior.spinImageSize??p.spinNumberImageSize,40,1200,760),resultImageSize:clamp(row.querySelector('.outcomeResultImageSize')?.value??prior.resultImageSize,40,1200,760),spinTextEnabled:row.querySelector('.outcomeSpinTextEnabled')?.checked!==false,spinText:row.querySelector('.outcomeSpinText')?.value.trim()||'',spinTextColor:row.querySelector('.outcomeSpinTextColor')?.value||prior.spinTextColor||'#ffffff',spinTextSize:clamp(row.querySelector('.outcomeSpinTextSize')?.value,14,600,130),spinFontFamily:row.querySelector('.outcomeSpinFontFamily')?.value||'global',resultTextEnabled:row.querySelector('.outcomeResultTextEnabled')?.checked!==false,resultText:row.querySelector('.outcomeResultText')?.value.trim()||'',resultTextColor:row.querySelector('.outcomeResultTextColor')?.value||prior.resultTextColor||'#ffffff',resultTextSize:clamp(row.querySelector('.outcomeResultTextSize')?.value,14,600,130),resultFontFamily:row.querySelector('.outcomeResultFontFamily')?.value||'global'}});const normalRows=[...el.querySelectorAll('.normalOutcomeMedia .advancedOutcomeRow')],upperRows=[...el.querySelectorAll('.upperOutcomeRows .advancedOutcomeRow')];p.outcomes=read(normalRows,p.outcomes||[],before?.outcomes||[]);p.upperOutcomes=read(upperRows,p.upperOutcomes||[],before?.upperOutcomes||[])})};
