// Pachinko-style gacha editor.
const pachinkoStages=[['spin','通常回転'],['reach','リーチ'],['cz','CZ'],['hit','大当たり'],['at','AT'],['upper','上位AT'],['lt','ラッキートリガー'],['end','終了画面']];
const pachinkoOpenSections=new Map();
function capturePachinkoOpen(){document.querySelectorAll('#pachinkoPatterns .pachinkoPattern').forEach(el=>{const open=new Set();el.querySelectorAll('details[data-p-section]').forEach(details=>{if(details.open)open.add(details.dataset.pSection)});pachinkoOpenSections.set(String(el.dataset.id||''),open)})}
function pachinkoSectionOpen(p,key,initial=false){const saved=pachinkoOpenSections.get(String(p.id||''));return saved?saved.has(key):initial}
function stageEditor(p,key,label){return `<section class="pachinkoStage"><h4>${label}</h4><div class="field"><label>画像・動画</label><input class="pachinkoMediaFile" data-stage="${key}" data-kind="animation" type="file" accept="image/*,video/mp4,video/webm"><span class="note">${p[key+'AnimationName']||'未設定'}</span></div><div class="field"><label>音源</label><input class="pachinkoMediaFile" data-stage="${key}" data-kind="audio" type="file" accept="audio/*"><span class="note">${p[key+'AudioName']||'未設定'}</span></div><div class="cardSizeGrid"><div class="field"><label>表示時間（秒）</label><input class="pachinkoStageSeconds" data-stage="${key}" type="number" min="0.2" max="120" step="0.1" value="${p[key+'Seconds']??3}"></div><div class="field"><label>音量（%）</label><input class="pachinkoStageVolume" data-stage="${key}" type="number" min="0" max="100" value="${p[key+'AudioVolume']??75}"></div></div><div class="missionTop"><button class="secondary clearPachinkoMedia" data-stage="${key}" data-kind="animation" type="button">画像・動画解除</button><button class="secondary clearPachinkoMedia" data-stage="${key}" data-kind="audio" type="button">音源解除</button></div></section>`}
function pachinkoHtml(p,i){return `<article class="gachaPattern pachinkoPattern" data-id="${p.id}"><div class="gachaPatternHead"><span class="gachaPatternIndex">パチンコ ${i+1}</span><strong>${p.name||'パチンコガチャ'}</strong></div><div class="cardSizeGrid"><div class="field"><label>パターン名</label><input class="pName" maxlength="60" value="${p.name||''}"></div><div class="field"><label>対象ギフト</label><div class="giftInputRow"><input class="pGift" value="${p.giftName||''}"><button class="secondary pGiftPick" type="button">ギフトを選択</button></div></div><label class="toggle"><input class="pEnabled" type="checkbox" ${p.enabled!==false?'checked':''}>このパターンを稼働</label><div class="field"><label>レイアウト</label><select class="pEffect"><option value="card" ${p.effectStyle!=='fullscreen'?'selected':''}>カード内</option><option value="fullscreen" ${p.effectStyle==='fullscreen'?'selected':''}>画面いっぱい</option></select></div></div>
<details data-p-section="basic" ${pachinkoSectionOpen(p,'basic',true)?'open':''}><summary>基本抽選・回転</summary><div class="cardSizeGrid"><div class="field"><label>ギフト1回の回転数</label><input class="pSpins" type="number" min="1" max="10000" value="${p.spinsPerGift??10}"></div><div class="field"><label>当たり確率（分子）</label><input class="pHitNum" type="number" min="1" value="${p.hitNumerator??1}"></div><div class="field"><label>当たり確率（分母）</label><input class="pHitDen" type="number" min="1" value="${p.hitDenominator??199}"></div><div class="field"><label>1回転の表示秒数</label><input class="pSpinSeconds" type="number" min="0.05" max="30" step="0.05" value="${p.spinSeconds??0.8}"></div><div class="field"><label>テスト再生速度</label><select class="pTestSpeed"><option value="1" ${Number(p.testPlaybackSpeed??1)===1?'selected':''}>設定時間どおり</option><option value="0.5" ${Number(p.testPlaybackSpeed)===0.5?'selected':''}>2倍速</option><option value="0.2" ${Number(p.testPlaybackSpeed)===0.2?'selected':''}>5倍速</option></select><span class="note">本番のギフト発動は常に設定時間どおりです。</span></div><div class="field"><label>大当たり基本WIN</label><input class="pBaseWin" type="number" min="0" value="${p.baseWin??10}"></div></div></details>
<details data-p-section="cz" ${pachinkoSectionOpen(p,'cz')?'open':''}><summary>CZ・時短</summary><div class="cardSizeGrid"><label class="toggle"><input class="pCzEnabled" type="checkbox" ${p.czEnabled?'checked':''}>CZを使う</label><div class="field"><label>CZ成功率（%）</label><input class="pCzRate" type="number" min="0" max="100" value="${p.czRate??50}"></div><label class="toggle"><input class="pShortEnabled" type="checkbox" ${p.timeShortEnabled?'checked':''}>時短を使う</label><div class="field"><label>時短回転数</label><input class="pShortSpins" type="number" min="0" max="10000" value="${p.timeShortSpins??50}"></div><div class="field"><label>時短の当たり分母（1/○）</label><input class="pShortDen" type="number" min="1" value="${p.timeShortHitDenominator??99}"></div></div></details>
<details data-p-section="at" ${pachinkoSectionOpen(p,'at')?'open':''}><summary>AT・上位AT・ラッキートリガー</summary><div class="cardSizeGrid"><label class="toggle"><input class="pAtEnabled" type="checkbox" ${p.atEnabled!==false?'checked':''}>ATを使う</label><div class="field"><label>AT突入率（%）</label><input class="pAtEntry" type="number" min="0" max="100" value="${p.atEntryRate??50}"></div><div class="field"><label>AT継続率（%）</label><input class="pAtContinue" type="number" min="0" max="100" value="${p.atContinuationRate??80}"></div><div class="field"><label>AT WIN 最小／最大</label><div class="cardSizeGrid"><input class="pAtMin" type="number" min="0" value="${p.atMinWin??5}"><input class="pAtMax" type="number" min="0" value="${p.atMaxWin??20}"></div></div><label class="toggle"><input class="pUpperEnabled" type="checkbox" ${p.upperEnabled?'checked':''}>上位ATを使う</label><div class="field"><label>上位突入率／継続率（%）</label><div class="cardSizeGrid"><input class="pUpperEntry" type="number" min="0" max="100" value="${p.upperEntryRate??10}"><input class="pUpperContinue" type="number" min="0" max="100" value="${p.upperContinuationRate??90}"></div></div><div class="field"><label>上位 WIN 最小／最大</label><div class="cardSizeGrid"><input class="pUpperMin" type="number" min="0" value="${p.upperMinWin??20}"><input class="pUpperMax" type="number" min="0" value="${p.upperMaxWin??50}"></div></div><label class="toggle"><input class="pLtEnabled" type="checkbox" ${p.luckyTriggerEnabled?'checked':''}>ラッキートリガーを使う</label><div class="field"><label>LT突入率／継続率（%）</label><div class="cardSizeGrid"><input class="pLtEntry" type="number" min="0" max="100" value="${p.luckyTriggerRate??5}"><input class="pLtContinue" type="number" min="0" max="100" value="${p.luckyTriggerContinuationRate??95}"></div></div><div class="field"><label>LT WIN 最小／最大</label><div class="cardSizeGrid"><input class="pLtMin" type="number" min="0" value="${p.luckyTriggerMinWin??50}"><input class="pLtMax" type="number" min="0" value="${p.luckyTriggerMaxWin??100}"></div></div></div></details>
<details data-p-section="media" ${pachinkoSectionOpen(p,'media')?'open':''}><summary>見た目と演出素材</summary><div class="cardAppearanceGrid"><div class="field"><label>背景色</label><input class="pCardBg" type="color" value="${p.cardBg||'#120b18'}"></div><div class="field"><label>アクセント色</label><input class="pAccent" type="color" value="${p.accentColor||'#ff3d66'}"></div><div class="field"><label>標準文字色（個別未設定時）</label><input class="pText" type="color" value="${p.textColor||'#ffffff'}"></div><div class="field"><label>標準文字サイズ（個別未設定時）</label><input class="pFontSize" type="number" min="18" max="300" value="${p.fontSize??64}"></div></div><div class="stageMediaGrid">${pachinkoStages.map(x=>stageEditor(p,...x)).join('')}</div></details>${textRoleEditor(p,pachinkoTextRoleLabels,'pachinko')}
<div class="missionTop"><button class="testPachinko" type="button">このパターンをテスト</button><button class="secondary copyPachinko" type="button">複製</button><button class="secondary togglePachinko" type="button">${p.enabled!==false?'停止':'再開'}</button><button class="danger deletePachinko" type="button">削除</button></div></article>`}
