function collectPachinko(){const machine=state.pachinkoGacha||{patterns:[],queue:[],history:[],event:{}};machine.patterns=[...document.querySelectorAll('.pachinkoPattern')].map((el,i)=>{const old=machine.patterns[i]||{},v=s=>el.querySelector(s)?.value,c=s=>el.querySelector(s)?.checked===true,p={...old,id:el.dataset.id,name:v('.pName')||`パチンコ${i+1}`,giftName:(v('.pGift')||'').trim(),enabled:c('.pEnabled'),effectStyle:v('.pEffect'),spinsPerGift:clamp(v('.pSpins'),1,10000,10),hitNumerator:clamp(v('.pHitNum'),1,1000000,1),hitDenominator:clamp(v('.pHitDen'),1,1000000,199),spinSeconds:clamp(v('.pSpinSeconds'),.05,30,.8),baseWin:clamp(v('.pBaseWin'),0,999999,10),czEnabled:c('.pCzEnabled'),czRate:clamp(v('.pCzRate'),0,100,50),timeShortEnabled:c('.pShortEnabled'),timeShortSpins:clamp(v('.pShortSpins'),0,10000,50),timeShortHitDenominator:clamp(v('.pShortDen'),1,1000000,99),atEnabled:c('.pAtEnabled'),atEntryRate:clamp(v('.pAtEntry'),0,100,50),atContinuationRate:clamp(v('.pAtContinue'),0,100,80),atMinWin:clamp(v('.pAtMin'),0,999999,5),atMaxWin:clamp(v('.pAtMax'),0,999999,20),upperEnabled:c('.pUpperEnabled'),upperEntryRate:clamp(v('.pUpperEntry'),0,100,10),upperContinuationRate:clamp(v('.pUpperContinue'),0,100,90),upperMinWin:clamp(v('.pUpperMin'),0,999999,20),upperMaxWin:clamp(v('.pUpperMax'),0,999999,50),luckyTriggerEnabled:c('.pLtEnabled'),luckyTriggerRate:clamp(v('.pLtEntry'),0,100,5),luckyTriggerContinuationRate:clamp(v('.pLtContinue'),0,100,95),luckyTriggerMinWin:clamp(v('.pLtMin'),0,999999,50),luckyTriggerMaxWin:clamp(v('.pLtMax'),0,999999,100),cardBg:v('.pCardBg'),accentColor:v('.pAccent'),textColor:v('.pText'),fontSize:clamp(v('.pFontSize'),18,300,64)};el.querySelectorAll('.pachinkoStageSeconds').forEach(x=>p[x.dataset.stage+'Seconds']=clamp(x.value,.2,120,3));el.querySelectorAll('.pachinkoStageVolume').forEach(x=>p[x.dataset.stage+'AudioVolume']=clamp(x.value,0,100,75));return p});state.pachinkoGacha=machine}
