function collectUnifiedTextSettings(){document.querySelectorAll('#gachaPatterns > .gachaPattern').forEach(el=>{const p=(state.gacha?.patterns||[]).find(item=>String(item.id)===String(el.dataset.id));if(!p||!el.querySelector('.textRoleEditor[data-text-scope="gacha"]'))return;p.textRoles=collectTextRoles(el,p.textRoles||{});const editor=el.querySelector('.textRoleEditor[data-text-scope="gacha"]');p.textGlowEnabled=editor.querySelector('.unifiedGlowEnabled')?.checked===true;p.textGlowColor=editor.querySelector('.unifiedGlowColor')?.value||p.textGlowColor||'#e52b3c';p.textGlowStrength=clamp(editor.querySelector('.unifiedGlowStrength')?.value,0,40,12)});document.querySelectorAll('#pachinkoPatterns .pachinkoPattern').forEach(el=>{const p=(state.pachinkoGacha?.patterns||[]).find(item=>String(item.id)===String(el.dataset.id));if(p&&el.querySelector('.textRoleEditor[data-text-scope="pachinko"]'))p.textRoles=collectTextRoles(el,p.textRoles||{})})}
const collectBeforeUnifiedTextSettings=window.collect;window.collect=function(){collectBeforeUnifiedTextSettings();collectUnifiedTextSettings()};
function renderPachinko(){const machine=state.pachinkoGacha||{patterns:[],queue:[],history:[],event:{}};const host=byId('pachinkoPatterns');if(!host)return;capturePachinkoOpen();host.innerHTML=(machine.patterns||[]).map(pachinkoHtml).join('');byId('pachinkoQueueStatus').textContent=(machine.event?.active?'抽選中・':'')+(machine.queue?.length?`${machine.queue.length}件待機中`:'待機なし');host.querySelectorAll('.pachinkoPattern').forEach((el,i)=>bindPachinko(el,i));}
function bindPachinko(el,i){const pattern=state.pachinkoGacha.patterns[i];el.querySelectorAll('details[data-p-section]').forEach(details=>details.addEventListener('toggle',()=>{const key=String(el.dataset.id||''),open=pachinkoOpenSections.get(key)||new Set();if(details.open)open.add(details.dataset.pSection);else open.delete(details.dataset.pSection);pachinkoOpenSections.set(key,open)}));el.querySelectorAll('input:not([type=file]),select').forEach(x=>x.addEventListener(x.type==='checkbox'||x.tagName==='SELECT'?'change':'input',save));el.querySelector('.pGiftPick').onclick=()=>openGiftPicker(el.querySelector('.pGift'));el.querySelector('.copyPachinko').onclick=()=>{collectPachinko();const copy=JSON.parse(JSON.stringify(state.pachinkoGacha.patterns[i]));copy.id='pachinko-'+Date.now();copy.name+=' コピー';copy.giftName='';state.pachinkoGacha.patterns.splice(i+1,0,copy);renderPachinko();save()};el.querySelector('.togglePachinko').onclick=()=>{collectPachinko();state.pachinkoGacha.patterns[i].enabled=!state.pachinkoGacha.patterns[i].enabled;renderPachinko();save()};el.querySelector('.deletePachinko').onclick=()=>{if(!confirm(`「${pattern.name}」を削除しますか？`))return;collectPachinko();state.pachinkoGacha.patterns.splice(i,1);renderPachinko();save()};el.querySelector('.testPachinko').onclick=async()=>{try{collectPachinko();await persist();await postJson('/api/pachinko/test',{patternId:pattern.id});setStatus('パチンコガチャのテストを開始しました（テスト用の短縮再生）')}catch(e){setStatus('テストできませんでした：'+e.message)}};el.querySelectorAll('.pachinkoMediaFile').forEach(input=>input.onchange=()=>uploadPachinkoMedia(pattern,input.dataset.stage,input.dataset.kind,input.files[0]));el.querySelectorAll('.clearPachinkoMedia').forEach(button=>button.onclick=()=>uploadPachinkoMedia(pattern,button.dataset.stage,button.dataset.kind,null,true));bindTextRoleEditor(el,pattern,'pachinko')}
async function uploadPachinkoMedia(pattern,stage,kind,file,clear=false){if(file&&file.size>(kind==='audio'?15:30)*1024*1024){setStatus((kind==='audio'?'音源は15MB':'画像・動画は30MB')+'以下にしてください');return}try{collectPachinko();await persist();const d=await postJson('/api/pachinko/media',{patternId:pattern.id,stage,kind,clear,...(file?{name:file.name,dataUrl:await readFile(file)}:{})});state.pachinkoGacha=d.pachinkoGacha;renderPachinko();setStatus(clear?'演出素材を解除しました':'演出素材を保存しました')}catch(e){setStatus('演出素材を変更できませんでした：'+e.message)}}
byId('addPachinkoPattern').onclick=()=>{collectPachinko();state.pachinkoGacha=state.pachinkoGacha||{patterns:[],queue:[],history:[],event:{}};state.pachinkoGacha.patterns.push(blankPachinko());renderPachinko();save()};
const collectBeforePachinko=window.collect;window.collect=function(){collectBeforePachinko();collectPachinko()};
const renderSettingsBefore6608=renderSettings;renderSettings=function(){renderSettingsBefore6608();renderPachinko();renderWinCounterSettings();const w=state.giftWall||{};byId('giftWallScrollStyle').value=w.scrollStyle||'page';byId('giftWallScrollSpeed').value=w.scrollSpeed??60;byId('giftWallLoop').checked=w.loop!==false;byId('giftWallNewestFirst').checked=w.newestFirst!==false};
window.renderAll=function(){renderSettings()};

// Keep live pachinko queue status current without rebuilding editors.
setInterval(async()=>{try{const fresh=await get();if(!fresh?.pachinkoGacha)return;state.pachinkoGacha=state.pachinkoGacha||{};state.pachinkoGacha.event=fresh.pachinkoGacha.event;state.pachinkoGacha.queue=fresh.pachinkoGacha.queue;const q=byId('pachinkoQueueStatus');if(q)q.textContent=(fresh.pachinkoGacha.event?.active?'抽選中・':'')+(fresh.pachinkoGacha.queue?.length?`${fresh.pachinkoGacha.queue.length}件待機中`:'待機なし')}catch(e){}},700);
